export interface SiteInviteRequest {
  /** The role ids to be assigned */
  policyIds?: string[];
  /**
   * Invitee email
   * @format EMAIL
   */
  email?: string;
  /**
   * Booking staff id
   * @internal
   * @format GUID
   */
  staffId?: string | null;
  /**
   * Invite purpose
   * @internal
   */
  invitePurpose?: string | null;
  /** The language of emails that will be used only for recipients that don't have a user, in case this parameter is unspecified, the sender's language will be used instead */
  defaultEmailLanguage?: string | null;
  /**
   * An indicator for suppressing (not sending) emails to the assignees.
   * @internal
   */
  suppressEmail?: boolean;
  /** Location restriction for the invite. */
  locationRestriction?: LocationRestriction;
}

export interface LocationRestriction {
  /**
   * @format GUID
   * @maxSize 20
   */
  locationIds?: string[];
}

export interface SiteInviteResponse {
  /** Invites that were sent. */
  invite?: SiteInvite;
}

export interface BulkSiteInviteRequest {
  /** Role IDs, referred to as policy IDs, to assign to the contributors. */
  policyIds: string[];
  /**
   * Email addresses to which the invites should be sent.
   * @minSize 1
   * @maxSize 10
   */
  emails: string[];
  /** Details explaining the purpose of the invite. */
  invitePurpose?: string | null;
  /** Language of emails to send. Relevant only for recipients that don't currently have a Wix user ID. Default: Site owner's language. */
  defaultEmailLanguage?: string | null;
  /** Location restriction for the invite. */
  locationRestriction?: LocationRestriction;
}

export interface BulkSiteInviteResponse {
  /** Invites that were sent successfully. */
  invites?: SiteInvite[];
  /**
   * Deprecated: use `failed_invites`. Populated in parallel for existing clients.
   * @deprecated Deprecated: use `failed_invites`. Populated in parallel for existing clients.
   * @replacedBy failed_invites
   * @targetRemovalDate 2027-08-01
   */
  failedEmails?: string[];
  /** Invites that failed, with the reason for each. */
  failedInvites?: FailedSiteInvite[];
}

export interface FailedSiteInvite {
  /**
   * Email address the invite was addressed to.
   * @format EMAIL
   */
  email?: string;
  /** Why this invite failed. */
  reason?: SiteInviteFailureReasonWithLiterals;
}

export enum SiteInviteFailureReason {
  /** Failure reason could not be determined. */
  UNKNOWN_FAILURE_REASON = 'UNKNOWN_FAILURE_REASON',
  /** This person owns the site. */
  USER_IS_SITE_OWNER = 'USER_IS_SITE_OWNER',
  /** This person has access to the site as a member of the requester's team. */
  USER_ON_REQUESTER_TEAM = 'USER_ON_REQUESTER_TEAM',
  /** This person has access to the site as a member of a team that is not the requester's. */
  USER_ON_ANOTHER_TEAM = 'USER_ON_ANOTHER_TEAM',
  /** This person's own account holds a collaborator assignment on the site. */
  USER_VIA_COLLABORATOR_ACCOUNT = 'USER_VIA_COLLABORATOR_ACCOUNT',
  /** This person already has access, but the source could not be determined. */
  USER_ALREADY_HAS_ACCESS = 'USER_ALREADY_HAS_ACCESS',
  /** An invite for this email address already exists on the site - pending, declined or expired. */
  INVITE_ALREADY_EXISTS = 'INVITE_ALREADY_EXISTS',
}

/** @enumType */
export type SiteInviteFailureReasonWithLiterals =
  | SiteInviteFailureReason
  | 'UNKNOWN_FAILURE_REASON'
  | 'USER_IS_SITE_OWNER'
  | 'USER_ON_REQUESTER_TEAM'
  | 'USER_ON_ANOTHER_TEAM'
  | 'USER_VIA_COLLABORATOR_ACCOUNT'
  | 'USER_ALREADY_HAS_ACCESS'
  | 'INVITE_ALREADY_EXISTS';

